def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers parentheses (), square brackets [], and curly braces {}.
    All other characters are ignored.
    """
    # Mapping of opening brackets to corresponding closing brackets
    pairs = {'(': ')', '[': ']', '{': '}'}
    closing = set(pairs.values())
    stack = []
    for ch in s:
        if ch in pairs:
            # push expected closing bracket
            stack.append(pairs[ch])
        elif ch in closing:
            # if no opening or mismatch, return False
            if not stack or stack[-1] != ch:
                return False
            stack.pop()
        # ignore other characters
    return not stack

