def solve(s):
    """Run-length encoding of the input sequence.
    Accepts any iterable of hashable items (including strings, lists, tuples).
    Returns a list of [item, count] pairs for each maximal run of equal items.
    """
    # If s is None or not iterable, return empty list
    try:
        iterator = iter(s)
    except TypeError:
        return []
    result = []
    prev = None
    count = 0
    for ch in iterator:
        if count == 0:
            prev = ch
            count = 1
        elif ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    if count:
        result.append([prev, count])
    return result

