{"task_id": "T06", "code": "def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Returns the integer result, with division truncating toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python's int() truncates toward zero for float results.
                # Avoid float overflow by using // and correcting sign.
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Compute truncating division toward zero
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    res = -res
                stack.append(res)
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0"}

