def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Patience sorting algorithm in O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find leftmost tail >= x for strictly increasing use bisect_left
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

