def solve(grid):
    """Return the number of islands in a binary matrix.
    Islands are groups of orthogonally adjacent cells with value 1.
    Handles empty grid and jagged rows gracefully.
    """
    # Guard against invalid input
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        visited.add((r, c))
        while stack:
            x, y = stack.pop()
            # Explore 4 directions
            for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows:
                    # Guard against jagged rows
                    if ny < 0 or ny >= len(grid[nx]):
                        continue
                    if (nx, ny) not in visited and grid[nx][ny] == 1:
                        visited.add((nx, ny))
                        stack.append((nx, ny))
    islands = 0
    for i in range(rows):
        cols_i = len(grid[i])
        for j in range(cols_i):
            if grid[i][j] == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

